create table if not exists spiritual.planetary_hours ( id bigint generated always as identity primary key, calc_date date not null, sunrise timestamptz not null, sunset timestamptz not null, next_sunrise timestamptz not null, day_ruler text not null, hours_json jsonb not null, calculated_by uuid not null references identity.profiles (id) default auth.uid(), tenant_id uuid references core.tenants (id), created_at timestamptz default now() );
